   209→    // Traiter par lots de 10 pour éviter les surcharges
   210→    const results: FavoriteEnrichmentResult[] = [];
   211→    const batches: string[][] = [];
   212→    for (let i = 0; i < favoriteIds.length; i += 10) {
   213→      batches.push(favoriteIds.slice(i, i + 10));
