   250→    // Logique de génération de données réalistes basées sur l'âge du bien
   251→    let energyClass = "D";
   252→    let energyConsumption = 200;
   253→    
   254→    if (yearBuilt < 1975) {
   255→      energyClass = "F";
   256→      energyConsumption = 350;
   257→    } else if (yearBuilt < 1990) {
   258→      energyClass = "E";
   259→      energyConsumption = 280;
   260→    } else if (yearBuilt < 2000) {
   261→      energyClass = "D";
   262→      energyConsumption = 220;
   263→    } else if (yearBuilt < 2010) {
   264→      energyClass = "C";
   265→      energyConsumption = 150;
   266→    } else {
   267→      energyClass = "B";
   268→      energyConsumption = 100;
   269→    }
   270→
   271→    return {
   272→      dpe: {
   273→        id: `mock_${favoriteId}`,
   274→        address: favorite.property.address,
   275→        postalCode: favorite.property.postalCode,
   276→        city: favorite.property.city,
   277→        propertyType: this.normalizePropertyType(favorite.property.category),
   278→        surface,
   279→        yearBuilt,
   280→        livingArea: surface,
   281→        energyConsumption: {
   282→          value: energyConsumption,
   283→          unit: "kWh_ep/m².an",
   284→          maxAuthorized: 450,
   285→          class: energyClass,
   286→        },
   287→        gesEmission: {
   288→          value: Math.round(energyConsumption * 0.15),
   289→          unit: "kgCO2/m².an",
   290→          maxAuthorized: 80,
   291→          class: energyClass,
   292→        },
   293→        mainEnergyType: "electricity",
   294→        dpeDate: new Date().toISOString().split('T')[0],
   295→        dpeValidity: new Date(Date.now() + 10 * 365 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
   296→        dataSource: "mock",
   297→        lastUpdated: new Date().toISOString(),
   298→      },
   299→      estimatedAnnualCost: Math.round(energyConsumption * surface * 0.25),
   300→      estimatedMonthlyCost: Math.round(energyConsumption * surface * 0.25 / 12),
   301→      rentalRestrictionRisk: energyClass === "F" || energyClass === "G" ? "critical" : "low",
   302→      renovationRequired: energyClass === "F" || energyClass === "G" || energyClass === "E",
   303→      renovationPriority: energyClass === "G" ? "high" : energyClass === "F" ? "medium" : "low",
   304→      estimatedRenovationCost: energyClass === "G" ? 25000 : energyClass === "F" ? 15000 : energyClass === "E" ? 8000 : 0,
   305→      performanceScore: energyClass === "A" ? 95 : energyClass === "B" ? 85 : energyClass === "C" ? 70 : energyClass === "D" ? 55 : energyClass === "E" ? 40 : energyClass === "F" ? 25 : 15,
   306→      energyEfficiencyRating: energyClass === "A" || energyClass === "B" ? "excellent" : energyClass === "C" || energyClass === "D" ? "good" : energyClass === "E" ? "average" : energyClass === "F" ? "poor" : "very_poor",
   307→      environmentalImpactRating: energyClass === "A" || energyClass === "B" ? "excellent" : energyClass === "C" ? "good" : energyClass === "D" ? "average" : energyClass === "E" ? "poor" : "very_poor",
   308→      recommendations: this.generateMockRecommendations(energyClass),
