   315→  /**
   316→   * Calcule un score de confiance basé sur l'analyse DPE
   317→   */
   318→  private calculateConfidenceScore(dpeAnalysis: {
   319→    dataSource?: string;
   320→    confidenceLevel?: string;
   321→    dpe: { energyConsumption: { class: string } };
   322→  }): number {
   323→    let score = 50; // Score de base
   324→
   325→    // Bonus pour les données réelles vs mockées
   326→    if (dpeAnalysis.dataSource === "api") {
   327→      score += 30;
   328→    } else if (dpeAnalysis.dataSource === "mock") {
   329→      score += 10;
   330→    }
   331→
   332→    // Bonus pour la qualité des données
   333→    if (dpeAnalysis.confidenceLevel === "high") {
   334→      score += 20;
   335→    } else if (dpeAnalysis.confidenceLevel === "medium") {
   336→      score += 10;
   337→    }
   338→
   339→    // Malus pour les classes d'énergie mauvaises (peuvent indiquer des données peu fiables)
   340→    if (dpeAnalysis.dpe.energyConsumption.class === "G") {
   341→      score -= 10;
   342→    }
   343→
   344→    return Math.min(100, Math.max(0, score));
   345→  }
