   347→  /**
   348→   * Estime l'année de construction basée sur les caractéristiques du bien
   349→   */
   350→  private estimateYearBuilt(property: Property): number {
   351→    // Logique simple d'estimation - peut être améliorée
   352→    const currentYear = new Date().getFullYear();
   353→    
   354→    if (property.floor && property.totalFloors && property.floor > property.totalFloors * 0.8) {
   355→      // Dernier étage = probablement plus récent
   356→      return currentYear - 20;
   357→    }
   358→    
   359→    if (property.hasLift) {
   360→      // Avec ascenseur = probablement construit après 1970
   361→      return 1980;
   362→    }
   363→    
   364→    // Par défaut, estimation conservatrice
   365→    return 1975;
   366→  }
