   368→  /**
   369→   * Normalise le type de propriété
   370→   */
   371→  private normalizePropertyType(category: string): string {
   372→    const typeMap: Record<string, string> = {
   373→      apartment: "apartment",
   374→      house: "house",
   375→      commercial: "other",
   376→      default: "apartment",
   377→    };
   378→    
   379→    return typeMap[category.toLowerCase()] || typeMap.default;
   380→  }
