   382→  /**
   383→   * Extrait les coordonnées du champ geometry
   384→   */
   385→  private extractCoordinates(coordinates: unknown): [number, number] | null {
   386→    if (!coordinates) return null;
   387→    
   388→    try {
   389→      // Le format peut varier, ceci est une gestion simple
   390→      if (Array.isArray(coordinates) && coordinates.length === 2) {
   391→        return coordinates as [number, number];
   392→      }
   393→      
   394→      if (typeof coordinates === 'string') {
   395→        const coords = coordinates.split(',').map(Number);
   396→        if (coords.length === 2 && !isNaN(coords[0]) && !isNaN(coords[1])) {
   397→          return coords as [number, number];
   398→        }
   399→      }
   400→      
   401→      return null;
   402→    } catch {
   403→      return null;
   404→    }
   405→  }
   406→
   407→  /**
   408→   * Génère des recommandations simulées
   409→   */
   410→  private generateMockRecommendations(energyClass: string): {
   411→    category: string;
   412→    description: string;
   413→    estimatedCost: number;
   414→    priority: string;
   415→  }[] {
   416→    const recommendations: {
   417→      category: string;
   418→      description: string;
   419→      estimatedCost: number;
   420→      priority: string;
   421→    }[] = [];
   422→
   423→    if (energyClass === "G" || energyClass === "F") {
   424→      recommendations.push({
   425→        category: "Isolation",
   426→        description: "Isolation thermique des murs et combles",
   427→        estimatedCost: 12000,
   428→        priority: "high",
   429→      });
   430→      recommendations.push({
   431→        category: "Chauffage",
   432→        description: "Installation d'une chaudière à haute performance",
   433→        estimatedCost: 8000,
   434→        priority: "high",
   435→      });
   436→      recommendations.push({
   437→        category: "Menuiseries",
   438→        description: "Remplacement des fenêtres par du double vitrage",
   439→        estimatedCost: 6000,
   440→        priority: "medium",
   441→      });
   442→    } else if (energyClass === "E") {
   443→      recommendations.push({
   444→        category: "Isolation",
   445→        description: "Amélioration de l'isolation des combles",
   446→        estimatedCost: 3000,
   447→        priority: "medium",
   448→      });
   449→    }
   450→
   451→    return recommendations;
   452→  }
   453→}

