    67→      coordinates: property.coordinates,
    68→      price: property.price,
    69→      surface: property.surface,
    70→      category: property.category,
    71→      rooms: property.rooms,
    72→    };
    73→
    74→    const analysis = await this.analyzer.analyzeProperty(propertyToAnalyze);
    75→
    76→    // Cache pour 6 heures (données peu volatiles)
    77→    await dvfCache.setAnalysis(property.id, analysis, 6 * 60 * 60 * 1000);
