    65→      
    66→      // Calculer les coûts énergétiques
    67→      const energyCost = calculateEnergyCost(
    68→        dpe.energyConsumption.value,
    69→        dpe.mainEnergyType as "electricity" | "gas" | "fuel_oil" | "wood" | "network" | "other",
    70→        dpe.surface
    71→      );
    72→      
    73→      // Évaluer le risque réglementaire
    74→      const rentalRestrictionRisk = assessRentalRestrictionRisk(
    75→        dpe.energyConsumption.class,
    76→        dpe.gesEmission.class
    77→      );
    78→      
    79→      // Générer les recommandations
    80→      const recommendations = generateRenovationRecommendations(dpe);
    81→      
    82→      // Calculer le score de performance
    83→      const performanceScore = calculatePerformanceScore(dpe);
    84→      
    85→      // Évaluer les notes
    86→      const energyEfficiencyRating = assessEnergyEfficiencyRating(performanceScore);
    87→      const environmentalImpactRating = assessEnvironmentalImpactRating(dpe.gesEmission.class);
    88→      
    89→      // Estimer les coûts de rénovation
    90→      const estimatedRenovationCost = estimateRenovationCost(recommendations);
    91→      
    92→      // Calculer les comparaisons de coûts
    93→      const costComparisonToAverage = this.calculateCostComparison(dpe.energyConsumption.class);
    94→      
    95→      const analysis: DPEAnalysis = {
    96→        dpe,
    97→        estimatedAnnualCost: energyCost.annualAmount,
    98→        estimatedMonthlyCost: energyCost.monthlyAmount,
    99→        costComparisonToAverage,
   100→        rentalRestrictionRisk,
   101→        renovationRequired: rentalRestrictionRisk === "high" || rentalRestrictionRisk === "critical",
   102→        estimatedRenovationCost: estimatedRenovationCost > 0 ? estimatedRenovationCost : undefined,
   103→        renovationPriority: this.calculateRenovationPriority(rentalRestrictionRisk, performanceScore),
   104→        recommendations,
   105→        performanceScore,
   106→        energyEfficiencyRating,
   107→        environmentalImpactRating,
   108→        analysisDate: new Date().toISOString(),
   109→        confidenceLevel: this.calculateConfidenceLevel(dpe),
   110→        dataSource: dpe.dataSource,
   111→      };
   112→      
   113→      // Valider et retourner l'analyse
   114→      return DPEAnalysisSchema.parse(analysis);
   115→    } catch (error) {
   116→      if (error instanceof DPEServiceError) {
   117→        throw error;
   118→      }
   119→      throw new DPEServiceError(
   120→        `Erreur lors de l'analyse DPE: ${error instanceof Error ? error.message : 'Erreur inconnue'}`,
   121→        "API_ERROR",
   122→        error
   123→      );
   124→    }
   125→  }
