   189→  /**
   190→   * Recherche de DPE par critères
   191→   */
   192→  async searchDPE(request: DPESearchRequest): Promise<{
   193→    results: DPEAnalysis[];
   194→    total: number;
   195→    averageScore: number;
   196→  }> {
   197→    try {
   198→      const cacheKey = this.getCacheKey("search", request);
   199→      
   200→      // Vérifier le cache
   201→      if (this.cacheResults) {
   202→        const cached = this.cache.get(cacheKey);
   203→        if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
   204→          return cached.data;
   205→        }
   206→      }
   207→      
   208→      const response = await this.client.searchDPE(request);
   209→      
   210→      // Analyser chaque DPE
   211→       
   212→      const analyses: DPEAnalysis[] = [];
   213→      for (const dpe of response.results) {
   214→        try {
   215→          // eslint-disable-next-line no-await-in-loop
   216→          const analysis = await this.analyzeDPE(dpe);
   217→          analyses.push(analysis);
   218→        } catch (error) {
   219→          console.debug("Erreur d'analyse d'un DPE:", error);
   220→        }
   221→      }
   222→      
   223→      // Calculer le score moyen
   224→      const averageScore = analyses.length > 0
   225→        ? Math.round(analyses.reduce((sum, a) => sum + a.performanceScore, 0) / analyses.length)
   226→        : 0;
   227→      
   228→      const result = {
   229→        results: analyses,
   230→        total: response.total,
   231→        averageScore,
   232→      };
   233→      
   234→      // Mettre en cache
   235→      if (this.cacheResults) {
   236→        this.cache.set(cacheKey, {
   237→          data: result,
   238→          timestamp: Date.now(),
   239→        });
   240→      }
   241→      
   242→      return result;
   243→    } catch (error) {
   244→      if (error instanceof DPEServiceError) {
   245→        throw error;
   246→      }
   247→      throw new DPEServiceError(
   248→        `Erreur lors de la recherche DPE: ${error instanceof Error ? error.message : 'Erreur inconnue'}`,
   249→        "API_ERROR",
   250→        error
   251→      );
   252→    }
