   255→  /**
   256→   * Obtient un DPE pour une propriété spécifique
   257→   */
   258→  private async getDPEForProperty(property: {
   259→    address: string;
   260→    postalCode: string;
   261→    city: string;
   262→    coordinates?: [number, number];
   263→  }): Promise<DPE> {
   264→    const cacheKey = this.getCacheKey("property", property);
   265→    
   266→    // Vérifier le cache
   267→    if (this.cacheResults) {
   268→      const cached = this.cache.get(cacheKey);
   269→      if (cached && Date.now() - cached.timestamp < this.cacheTTL) {
   270→        return cached.data;
   271→      }
